class _DecisionTreeRegressorNode:
    """Node of a DecisionTreeRegressor tree (leaf when feature is None)."""

    __slots__ = ("value", "feature", "threshold", "left", "right")

    def __init__(self, value):
        self.value = value
        self.feature = None
        self.threshold = None
        self.left = None
